+fn judge_with_part_top(movement: Move, rim_top_z: f64) -> Vec<Warning> {
+    let region = bore();
+    let mut geometry = tool();
+    geometry.radius = 4.0;
+    geometry.shank_radius = 4.0;
+    let cutter = Cutter { tip_angle: 90.0, ..Cutter::flat(&geometry) };
+    let rims = [(Point2::new(0.0, 0.0), 2.5)];
