+        region: &region,
+        tool: &geometry,
+        cutter: Some(cutter),
+        mode: Mode::Boundary,
+        stock_top_z: 13.0,
+        rim_top_z: Some(rim_top_z),
+        clearance_z: 27.0,
+        gouge_tol: 0.01,
